C = dict(id='GL-26', title='Box Subscription Services', group='Business and Commerce', level=4,
 summary='Design and run a small subscription-box service: pick a theme, source and cost the box, set a fair price, ship on time and keep subscribers happy.',
 outcomes=['Explain the subscription model, churn and lifetime value.', 'Source and cost the contents of a box.', 'Analyse price, margin and break-even.', 'Create the box, packing and shipping plan, and a fair cancellation process.', 'Evaluate retention and satisfaction after the first cycles.'],
 task='Plan and deliver two cycles of a small box (at least 10 subscribers or practice buyers) with costings, packing, delivery and feedback.',
 cond='A theme, suppliers, packaging, a sign-up form, a spreadsheet, a mentor with retail experience and a peer circle. About 12 weeks part-time.',
 std='Landed cost per box and margin calculated; delivery on the promised day for 95% of boxes; cancellation possible in one click; consent kept; ratings of 4 of 5 or better; churn measured.',
 who='Small makers, shop owners, hobby experts, students.', req='None.',
 safety='Follow consumer rules on clear pricing, renewals and cancellation. Sell only safe, labelled goods. Use practice payments if you have no licensed partner.',
 mods=[
 ('The subscription idea', 'People subscribe for convenience, discovery or habit.', ['Pick a theme with repeat need: tea, craft, snacks, books, plant care.', 'Define the subscriber and the monthly promise.', 'Frequency and size.', 'Name and short story.'], 'Theme "Weekend Baker": 3 mixes, 1 tool, 1 recipe card each month.', 'Write theme, subscriber and promise.', 'Fit the promise into one sentence.'),
 ('Source and cost', 'Know the true cost of every item.', ['Quotes from at least two suppliers.', 'Landed cost = item + delivery in + tax + packaging.', 'Quality checks and samples.', 'Back-up suppliers.'], 'Item 2.00 + delivery in 0.30 + packaging 0.20 = 2.50 each (an estimate; check your market); five items = 12.50. Amounts are in your currency.', 'Cost one full box.', 'Calculate landed cost per item and per box correctly.'),
 ('Price and margin', 'Price must cover everything and leave profit.', ['Box cost + packing + shipping + fees + marketing.', 'Margin % = (price - cost) / price.', 'Break-even subscribers = fixed costs / margin per box.', 'Test willingness to pay.'], 'Price 25 a box; cost 12.50 + pack 1.50 + ship 4.00 + fee 0.90 = 18.90; margin 6.10 (24%); fixed 300 → 50 boxes to break even. Amounts are in your currency.', 'Build the pricing sheet.', 'Compute the break-even.'),
 ('Sign-up and rules', 'Be clear and fair.', ['Show price, renewal date and how to cancel before payment.', 'Consent for contact.', 'Pause and skip options.', 'Refund policy in plain words.'], 'The sign-up page says "25 per month, renews on the 5th, cancel any time in one click". Amounts are in your currency.', 'Draft sign-up page and policy.', 'Use plain words and a one-click cancel.'),
 ('Packing and surprise', 'Unboxing is the product.', ['Layout, protection, card, branding.', 'Weight and size for cheap shipping.', 'Test drop and shake.', 'Keep a few spares.'], 'Switching to a flat box saves 1.20 postage per box. Amounts are in your currency.', 'Pack and test five boxes.', 'Test that nothing breaks.'),
 ('Ship and track', 'Reliability keeps subscribers.', ['Cut-off dates and ship day.', 'Labels and tracking.', 'Handle failed deliveries and replacements.', 'Message before and after dispatch.'], '48 of 50 boxes arrive on the promised day = 96%.', 'Deliver cycle one.', 'Calculate the delivery rate.'),
 ('Retention and churn', 'Keeping a subscriber costs less than finding one.', ['Churn = cancellations / subscribers at start.', 'Lifetime value = margin per box x months kept.', 'Ask why they cancel.', 'Improve box, perks, community.'], '10 of 100 cancel: churn 10%; average life 10 months; lifetime margin 61. Amounts are in your currency.', 'Measure churn and survey leavers.', 'Record churn and reasons.'),
 ('Review and plan', 'Decide how to grow safely.', ['Cycle two improved by feedback.', 'Add a gift option or bundle.', 'Plan stock for growth.', 'Plan 90 days.'], 'Feedback says too many snacks: swap one for a tool; rating rises to 4.6.', 'Run cycle two and report.', 'Tie changes to feedback.')],
 quiz=[('What is churn?', 'The share of subscribers who cancel in a period.'), ('Landed cost?', 'Item plus inbound delivery, tax and packaging.'), ('Margin percent formula?', '(Price - cost) divided by price.'), ('Break-even subscribers?', 'Fixed costs divided by margin per box.'), ('What must sign-up show?', 'Price, renewal date and how to cancel.'), ('Why offer pause?', 'It keeps people who need a break.'), ('How to cut postage?', 'Lighter, flatter packs.'), ('What is lifetime value?', 'Margin per box times months kept.'), ('Why back-up suppliers?', 'To avoid missing a cycle.'), ('How measure happiness?', 'Ratings, comments and retention.')],
 rubric=[('Costing', 'Landed cost correct', 'Sensitivity to price changes'), ('Rules', 'Clear renewal and cancel', 'Reviewed by adviser'), ('Delivery', '95% on time', '98% with tracking messages'), ('Retention', 'Churn measured', 'Reasons used to improve'), ('Plan', 'Cycle two improved', 'Growth plan costed')],
 jobs=[('Subscription box coordinator', 'Plans and ships boxes'), ('Product curator', 'Selects items'), ('Customer care agent', 'Handles pauses and cancels'), ('Founder of a small box business', 'Runs the model')],
 next='E-Commerce Inventory Management; E-Commerce Growth Marketing; Ghost Kitchens.',
 local='Renewal and cancellation rules and import duties vary by place; check consumer law.',
 evidence='Your evidence: theme note, costing, pricing sheet, sign-up policy, packing test, delivery log, churn table and review.',
 ladder=[('Basics of subscriptions', 'Describe a subscription box and what a subscriber expects each month. Notes: look at one box you or a friend receive and list what is in it. Standard: five items listed with a guess of cost each.'), ('Awareness', 'Describe the box cycle (choose, buy, pack, ship, renew) and the reasons subscribers cancel. Notes: read public reviews of two boxes and list the top three complaints. Standard: each complaint matched to a cycle step.'), ('Foundation', 'Cost one box: items, packing, postage and loss, and set a price with margin. Notes: practice figures with currency. Standard: margin per box correct and a break-even number of subscribers.'), ('Practitioner', 'Pack and send five practice boxes, time each step and collect feedback. Notes: include one late and one damaged case. Standard: all five delivered or explained, with feedback recorded.'), ('Specialist', 'Plan and deliver two cycles of a small box for at least 10 subscribers or practice buyers, with costings, packing, delivery and feedback. Notes: report churn between cycles. Standard: cost per box checked against the plan and one change made from feedback.'), ('Advanced', 'Run several boxes with supplier contracts, a forecast and a cancellation policy. Notes: add a monthly churn and stock review. Standard: forecast within 10% and cancellation terms clear before sign-up.'), ('Super expert', 'Set the plan, churn and fulfilment method for subscription boxes and teach the managers who use it. Notes: re-read the consumer-subscription and cancellation rules for the place each year.')])

C['deep'] = dict(mods=[
 ('Choosing a theme you like instead of one that repeats.', 'A one-time gift theme has high churn; a consumable theme keeps subscribers.', 'Why will your subscriber want a second box?'),
 ('Pricing from the supplier quote only.', 'Landed cost with delivery in and packaging is 12.50, not the quoted 10.00.', 'What is your landed cost?'),
 ('Forgetting free shipping in the margin.', 'Free shipping of 4.00 cuts margin from 10.00 to 6.00.', 'Is shipping in your margin?'),
 ('Hiding cancel links.', 'One-click cancel from the account page; support not needed.', 'Where is cancel?'),
 ('Over-packing.', 'A flatter box saves 1.20 postage.', 'What is your packed weight?'),
 ('Promising a ship date you cannot meet.', 'Cut-off the 25th, ship on the 5th, communicate delays at once.', 'What is your ship date?'),
 ('Ignoring leavers.', 'Exit survey shows "too many snacks"; change the mix.', 'Why did subscribers leave?'),
 ('Skipping cycle-two changes.', 'Swap one item based on feedback; rating rises.', 'What changed in cycle two?')],
 gloss=[('Churn', 'Share of subscribers who cancel.'), ('Landed cost', 'Full cost to get an item ready to ship.'), ('Break-even', 'Point where income equals costs.'), ('Lifetime value', 'Margin from one subscriber over their stay.'), ('Cut-off date', 'Last day to join for the next box.'), ('Unboxing', 'The experience of opening the box.')],
 cases=[('The late supplier', 'A key item arrives a week late.', 'What do you do?', 'Tell subscribers early, swap in an equal item or ship in two parts, and record the supplier failure.'),
        ('The cancellation complaint', 'A customer says they could not find cancel.', 'What now?', 'Refund the last charge if law requires, fix the cancel path and log the change.')])
